package org.brightstats.stats;
import java.util.*;import java.nio.file.*;import com.google.gson.*;
public final class HierarchyPipelineChecks {
 static int checks;static void require(boolean value,String message){checks++;if(!value)throw new AssertionError(message);}static void reject(Runnable action){try{action.run();throw new AssertionError("Invalid hierarchy accepted");}catch(IllegalArgumentException expected){checks++;}}
 public static void main(String[] args)throws Exception{Path output=Path.of(args[0]);Files.createDirectories(output);Random random=new Random(74119);int n=1200;double[][] data=new double[n][33];for(int i=0;i<n;i++){double g=random.nextGaussian();double[] h={.8*g+.6*random.nextGaussian(),.7*g+Math.sqrt(.51)*random.nextGaussian(),.75*g+Math.sqrt(.4375)*random.nextGaussian()};for(int factor=0;factor<9;factor++){double loc=.8*h[factor/3]+.6*random.nextGaussian();for(int j=0;j<3;j++)data[i][factor*3+j]=(.8+.1*j)*loc+.8*random.nextGaussian();}double m=.6*g+.8*random.nextGaussian(),y=.4*m+.3*g+.7*random.nextGaussian();for(int j=0;j<3;j++){data[i][27+j]=(.8+.1*j)*m+.8*random.nextGaussian();data[i][30+j]=(.8+.1*j)*y+.8*random.nextGaussian();}}List<PlsSem.Block> blocks=new ArrayList<>();List<PlsSem.Edge> edges=new ArrayList<>();for(int i=0;i<11;i++)blocks.add(new PlsSem.Block(i==9?"M":i==10?"Y":"L"+i,new int[]{3*i,3*i+1,3*i+2},PlsSem.Mode.A));for(int i=0;i<9;i++){edges.add(new PlsSem.Edge(i,9));edges.add(new PlsSem.Edge(i,10));}edges.add(new PlsSem.Edge(9,10));var options=PlsSem.Options.defaults();List<HigherOrderPls.Dimension> dimensions=new ArrayList<>();for(int i=0;i<3;i++)dimensions.add(new HigherOrderPls.Dimension("H"+i,new int[]{3*i,3*i+1,3*i+2},PlsSem.Mode.A,PlsSem.MeasurementType.REFLECTIVE,null));var first=new HigherOrderPls.Specification(new int[]{9,10},dimensions,List.of(new PlsSem.Edge(2,0),new PlsSem.Edge(3,0),new PlsSem.Edge(4,0),new PlsSem.Edge(2,1),new PlsSem.Edge(3,1),new PlsSem.Edge(4,1),new PlsSem.Edge(0,1)),options);var second=new HigherOrderPls.Specification(new int[]{0,1},List.of(new HigherOrderPls.Dimension("General",new int[]{2,3,4},PlsSem.Mode.A,PlsSem.MeasurementType.REFLECTIVE,null)),List.of(new PlsSem.Edge(2,0),new PlsSem.Edge(2,1),new PlsSem.Edge(0,1)),options);var model=new HierarchyPipeline.Model(blocks,edges,options,List.of(first,second));var settings=new Bootstrap.Options(40,611,.95);var composite=HierarchyPipeline.bootstrap(data,model,settings,null);var factor=FactorHierarchy.bootstrap(data,model,settings,null);require(composite.point().stages().size()==2&&factor.point().stages().size()==2,"Missing hierarchy level");require(composite.inference().successful()>=32&&factor.inference().successful()>=32,"Full-pipeline resampling failed");require(composite.point().originalColumns()==33&&composite.point().observations()==n,"Original data provenance changed");require(factor.point().stages().get(1).paths()[2][1]>.1&&factor.point().stages().get(1).paths()[2][1]<.8,"Implausible factor hierarchy estimate");var single=new HierarchyPipeline.Model(blocks,edges,options,List.of(first));var ordinary=HigherOrderPls.fit(data,blocks,edges,options,first);var one=HierarchyPipeline.fit(data,single).stages().getFirst();require(Arrays.deepEquals(ordinary.secondStage().pathCoefficients(),one.secondStage().pathCoefficients()),"Existing two-stage behavior changed");require(factor.point().warnings().stream().anyMatch(w->w.contains("never resampled")||w.contains("No artificial")),"Missing moment provenance warning");reject(()->new HierarchyPipeline.Model(blocks,edges,options,List.of()));reject(()->new HierarchyPipeline.Model(blocks,edges,options,Collections.nCopies(8,first)));var invalid=new HigherOrderPls.Specification(new int[]{9},List.of(new HigherOrderPls.Dimension("Bad",new int[]{0,1},PlsSem.Mode.A,PlsSem.MeasurementType.REFLECTIVE,null)),List.of(new PlsSem.Edge(1,0)),options);reject(()->FactorHierarchy.fit(data,new HierarchyPipeline.Model(blocks,edges,options,List.of(invalid))));Thread.currentThread().interrupt();try{HierarchyPipeline.fit(data,model);throw new AssertionError("Cancellation ignored");}catch(java.util.concurrent.CancellationException expected){checks++;}finally{Thread.interrupted();}JsonObject result=new JsonObject();Gson gson=new GsonBuilder().serializeNulls().serializeSpecialFloatingPointValues().setPrettyPrinting().create();result.add("observations",gson.toJsonTree(data));result.add("model",gson.toJsonTree(model));result.add("composite",gson.toJsonTree(composite));result.add("factor",gson.toJsonTree(factor));double[][] small=Arrays.copyOf(data,400);var bcaOptions=new Bootstrap.Options(40,882,.90,BootstrapIntervals.Method.BCA,RegressionBootstrap.Convention.STANDARD,true);var compositeBca=HierarchyPipeline.bootstrap(small,model,bcaOptions,null);var factorBca=FactorHierarchy.bootstrap(small,model,bcaOptions,null);require(compositeBca.inference().estimates().stream().anyMatch(e->e.parameter().family().equals("Path")&&Double.isFinite(e.lower())),"Composite hierarchy BCa unavailable");require(factorBca.inference().estimates().stream().anyMatch(e->e.parameter().family().equals("Path")&&Double.isFinite(e.lower())),"Factor hierarchy BCa unavailable");result.add("bcaObservations",gson.toJsonTree(small));result.add("compositeBca",gson.toJsonTree(compositeBca));result.add("factorBca",gson.toJsonTree(factorBca));
Files.writeString(output.resolve("cases.json"),gson.toJson(result));System.out.println("Hierarchy pipeline checks: "+checks);}
}
